100"><?php foreach($group['rows'] as$row):$id=(int)$row['id'];?><tr data-progress-row data-meeting-progress="<?=(float)$row['progress']?>"><td class="p-3"><strong class="text-slate-950"><?=pc_e($row['task_title'])?></strong><small class="block text-slate-500"><?=pc_e((string)($row['old_deadline']??''))?> → <?=pc_e((string)($row['new_deadline']??''))?></small></td><td class="p-2"><input name="tasks[<?=$id?>][unit_label]" value="<?=pc_e($row['unit_label'])?>" class="w-20 rounded-xl border border-slate-200 px-2 py-2"></td><td class="p-2"><input type="number" min="0.001" step="0.001" name="tasks[<?=$id?>][planned_quantity]" value="<?=(float)$row['planned_quantity']?>" data-planned class="w-28 rounded-xl border border-slate-200 px-2 py-2 text-right"></td><td class="p-2"><input type="number" value="<?=(float)$row['executed_quantity']?>" data-executed readonly class="w-28 rounded-xl border border-slate-100 bg-slate-100 px-2 py-2 text-right text-slate-600"></td><td class="p-3 text-center"><span data-technical class="rounded-full bg-indigo-50 px-3 py-1 font-black text-indigo-700"><?=number_format((float)$row['technical_rate'],1,',',' ')?>%</span></td><td class="p-2"><input type="number" min="0" step="0.01" name="tasks[<?=$id?>][client_billed_amount]" value="<?=(float)$row['client_billed_amount']?>" data-billed class="w-36 rounded-xl border border-slate-200 px-2 py-2 text-right"></td><td class="p-2"><input type="number" value="<?=(float)$row['executed_billed_amount']?>" data-executed-billed readonly class="w-36 rounded-xl border border-slate-100 bg-slate-100 px-2 py-2 text-right text-slate-600"></td><td class="p-3 text-center"><span data-financial class="rounded-full bg-orange-50 px-3 py-1 font-black text-orange-700"><?=number_format((float)$row['financial_rate'],1,',',' ')?>%</span></td><td class="p-2"><input name="tasks[<?=$id?>][observation]" value="<?=pc_e($row['observation'])?>" class="w-52 rounded-xl border border-slate-200 px-3 py-2"></td></tr><?php endforeach;?></tbod