<script>(()=>{const money=value=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(value)+' FCFA';const recalc=()=>{let totalBudget=0,totalExecuted=0,totalWeightedTech=0;document.querySelectorAll('[data-progress-group]').forEach(group=>{let taskBudget=0,executedAmount=0,weightedTech=0,technicalSum=0,count=0;group.querySelectorAll('[data-progress-row]').forEach(row=>{const rate=Math.min(100,Math.max(0,+row.dataset.meetingProgress||0)),p=+row.querySelector('[data-planned]').value||0,b=+row.querySelector('[data-billed]').value||0,e=p*rate/100,x=b*rate/100;row.querySelector('[data-executed]').value=e.toFixed(3);row.querySelector('[data-executed-billed]').value=x.toFixed(2);row.querySelector('[data-technical]').textContent=rate.toFixed(1)+'%';row.querySelector('[data-financial]').textContent=rate.toFixed(1)+'%';taskBudget+=b;executedAmount+=x;weightedTech+=rate*b;technicalSum+=rate;count++;});const entered=+group.querySelector('[data-group-budget]').value||0,budget=entered||taskBudget,technical=taskBudget?weightedTech/taskBudget:(count?technicalSum/count:0),financial=budget?Math.min(100,executedAmount/budget*100):0;group.querySelector('[data-group-tech]').textContent='Technique '+technical.toFixed(1)+'%';group.querySelector('[data-group-fin]').textContent='Financier '+financial.toFixed(1)+'%';totalBudget+=budget;totalExecuted+=executedAmount;totalWeightedTech+=technical*budget;});document.querySelector('[data-total-budget]').textContent=money(totalBudget);document.querySelector('[data-total-executed]').textContent=money(totalExecuted);document.querySelector('[data-total-technical]').textContent=(totalBudget?totalWeightedTech/totalBudget:0).toFixed(1)+'%';document.querySelector('[data-total-financial]').textContent=(totalBudget?Math.min(100,totalExecuted/totalBudget*100):0).toFixed(1)+'%';};document.querySelectorAll('#workProgressForm input').forEach(input=>input.addEventListener('input',recalc));recalc();})();</script>
